function initializeIncidentLanguage() {
  currentIncidentLanguage = detectIncidentLanguage();
  applyIncidentStaticTranslations();
  const selector = document.getElementById("incidentLanguageSelector");
  if (selector) {
    selector.value = currentIncidentLanguage;
    selector.addEventListener("change", () => {
      currentIncidentLanguage = normalizeIncidentLanguage(selector.value) || "en";
      saveIncidentLanguage(currentIncidentLanguage);
      rerenderIncidentLanguage();
    });
  }
}
